import boto3

def run_ocr(bucket_name, document_key):
    client = boto3.client('textract')
    response = client.detect_document_text(
        Document={'S3Object':{'Bucket': bucket_name, 'Name': document_key}}
    )
    text = ''
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            text += item['Text'] + ' '
    return text

from typing import Any, Dict, List, Union

class StorageRequest:
    def __init__(self, method: str, path: str, headers: Dict[str, str] = None, body: Union[str, bytes] = None):
        self.method = method
        self.path = path
        self.headers = headers if headers else {}
        self.body = body

class StorageResponse:
    def __init__(self, status_code: int, headers: Dict[str, str], body: Union[str, bytes]):
        self.status_code = status_code
        self.headers = headers
        self.body = body

def normalize_headers(headers: Dict[str, Any]) -> Dict[str, str]:
    return {k: str(v) for k, v in headers.items()}

def normalize_body(body: Union[str, bytes]) -> Union[str, bytes]:
    if isinstance(body, str):
        return body.strip()
    elif isinstance(body, bytes):
        return body.strip()
    else:
        raise ValueError('Body must be a string or bytes')

import boto3


class StorageClient:
    def __init__(self, aws_access_key_id, aws_secret_access_key, region_name):
        self.s3_client = boto3.client(
            's3',
            aws_access_key_id=aws_access_key_id,
            aws_secret_access_key=aws_secret_access_key,
            region_name=region_name
        )

    def get_client(self):
        return self.s3_client

import boto3

def list_prefix(bucket_name, prefix):
    s3_client = boto3.client('s3')
    response = s3_client.list_objects_v2(Bucket=bucket_name, Prefix=prefix)
    if 'Contents' in response:
        return [obj['Key'] for obj in response['Contents']]
    else:
        return []

import boto3

def get_object_metadata(bucket_name, object_key):
    s3 = boto3.client('s3')
    try:
        response = s3.head_object(Bucket=bucket_name, Key=object_key)
        return response
    except Exception as e:
        print(f"Error getting object metadata: {e}")
        return None

import boto3

def upload_to_s3(bucket_name, object_key, file_path):
    s3_client = boto3.client('s3')
    try:
        s3_client.upload_file(file_path, bucket_name, object_key)
        print(f'File uploaded successfully to {bucket_name}/{object_key}')
    except Exception as e:
        print(f'Error uploading file: {e}')


def upload_byte_stream_to_s3(bucket_name, object_key, byte_stream):
    s3_client = boto3.client('s3')
    try:
        s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=byte_stream)
        print(f'Byte stream uploaded successfully to {bucket_name}/{object_key}')
    except Exception as e:
        print(f'Error uploading byte stream: {e}')
